// Checkout conversion module - drives paid events from leads
const axios = require('axios');

module.exports = {
  async convertLead(leadId, amount) {
    // Simulate payment processing
    const result = await axios.post('http://localhost:4000/api/checkout', {
      leadId,
      amount,
      currency: 'USD'
    });
    return result.data;
  },

  async runConversionCycle() {
    // Fetch leads that are ready for conversion
    const leads = await axios.get('http://localhost:4000/api/leads?status=ready');
    for (const lead of leads.data) {
      try {
        await this.convertLead(lead.id, lead.amount);
        console.log(`Converted lead ${lead.id}`);
      } catch (err) {
        console.error(`Failed to convert lead ${lead.id}: ${err.message}`);
      }
    }
  }
};
